import{_ as r,a0 as s,w as i,s as d,ao as l,I as p,x as e,a1 as a,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"如何使用netstat命令验证DDOS入侵 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用netstat命令验证DDOS入侵 | LCTT (201406) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用netstat命令验证DDOS入侵 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用netstat命令验证DDOS入侵 | LCTT (201406) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201406/How to verify DDOS attack with netstat command on Linux Terminal","title":"如何使用netstat命令验证DDOS入侵","tag":"201406","desc":""},"relativePath":"201406/How to verify DDOS attack with netstat command on Linux Terminal.md","filePath":"[post].md"}'),D={name:"201406/How to verify DDOS attack with netstat command on Linux Terminal.md"};function m(c,t,u,T,f,S){const n=s("Link");return i(),d("div",null,[t[11]||(t[11]=l(`<h1 id="如何使用netstat命令验证ddos入侵" tabindex="-1">如何使用netstat命令验证DDOS入侵 <a class="header-anchor" href="#如何使用netstat命令验证ddos入侵" aria-label="Permalink to “如何使用netstat命令验证DDOS入侵”">​</a></h1><p>一般来说，服务器非常慢可能原因是多方面的，有可能是配置错误，脚本错误或者是一些奇诡的硬件。当然也有可能是有人对你的服务器进行 Dos (拒绝服务攻击)或者 DDOS (分布式拒绝服务攻击)。</p><p>Dos攻击或者DDos攻击目的是使服务器或者网络资源耗尽，使其他用户无法使用。一般来说，这种攻击主要针对重要的网站或服务，比如银行、信用卡支付网关甚至是根域名服务器。Dos攻击主要通过强制目标主机重启或大量消耗其主机资源，使得目标主机无法提供服务或者妨害主机和用户之间的通信的手段，使得主机无法提供正常的服务的。</p><p>在本文中你将知道如何在终端中使用netstat命令判断服务器是否遭受Dos攻击。</p><p>netstat命令的用户手册描述其作用是用来显示网络连接、路由表、接口统计、伪连接和组播成员的。</p><h3 id="一些例子和解释" tabindex="-1">一些例子和解释 <a class="header-anchor" href="#一些例子和解释" aria-label="Permalink to “一些例子和解释”">​</a></h3><pre><code>netstat -na
</code></pre><p>该命令将显示所有活动的网络连接。</p><pre><code>netstat -an | grep :80 | sort
</code></pre><p>显示所有80端口的网络连接并排序。这里的80端口是http端口，所以可以用来监控web服务。如果看到同一个IP有大量连接的话就可以判定单点流量攻击了。</p><pre><code>netstat -n -p|grep SYN_REC | wc -l
</code></pre><p>这个命令可以查找出当前服务器有多少个活动的 SYNC_REC 连接。正常来说这个值很小，最好小于5。 当有Dos攻击或者邮件炸弹的时候，这个值相当的高。尽管如此，这个值和系统有很大关系，有的服务器值就很高，也是正常现象。</p><pre><code>netstat -n -p | grep SYN_REC | sort -u
</code></pre><p>列出所有连接过的IP地址。</p><pre><code>netstat -n -p | grep SYN_REC | awk &#39;{print $5}&#39; | awk -F: &#39;{print $1}&#39;
</code></pre><p>列出所有发送SYN_REC连接节点的IP地址。</p><pre><code>netstat -ntu | awk &#39;{print $5}&#39; | cut -d: -f1 | sort | uniq -c | sort -n
</code></pre><p>使用netstat命令计算每个主机连接到本机的连接数。</p><pre><code>netstat -anp |grep &#39;tcp|udp&#39; | awk &#39;{print $5}&#39; | cut -d: -f1 | sort | uniq -c | sort -n
</code></pre><p>列出所有连接到本机的UDP或者TCP连接的IP数量。</p><pre><code>netstat -ntu | grep ESTAB | awk &#39;{print $5}&#39; | cut -d: -f1 | sort | uniq -c | sort -nr
</code></pre><p>检查 ESTABLISHED 连接并且列出每个IP地址的连接数量。</p><pre><code>netstat -plan|grep :80|awk {&#39;print $5&#39;}|cut -d: -f 1|sort|uniq -c|sort -nk 1
</code></pre><p>列出所有连接到本机80端口的IP地址和其连接数。80端口一般是用来处理HTTP网页请求。</p><h3 id="如何减少dos攻击" tabindex="-1">如何减少DOS攻击 <a class="header-anchor" href="#如何减少dos攻击" aria-label="Permalink to “如何减少DOS攻击”">​</a></h3><p>一旦你获得攻击服务器的IP地址你就可以使用以下命令拒绝此IP的所有连接。</p><pre><code>iptables -A INPUT 1 -s $IPADRESS -j DROP/REJECT
</code></pre><p>注意，你需要将 $IPADRESS 替换成需要拒绝连接的IP地址。</p><p>执行完以上命令后，使用以下命令结束所有的httpd连接以清理系统。</p><pre><code>killall -KILL httpd
</code></pre><p>然后执行以下命令重启httpd服务。</p><pre><code>service httpd start           #RedHat 系统 

/etc/init/d/apache2 restart   #Debian 系统
</code></pre><hr>`,33)),p("p",null,[t[1]||(t[1]=e("via: ",-1)),a(n,{href:"http://linuxaria.com/howto/how-to-verify-ddos-attack-with-netstat-command-on-linux-terminal"},{default:o(()=>[...t[0]||(t[0]=[e("http://linuxaria.com/howto/how-to-verify-ddos-attack-with-netstat-command-on-linux-terminal",-1)])]),_:1})]),p("p",null,[t[4]||(t[4]=e("译者：",-1)),a(n,{href:"https://github.com/shipsw"},{default:o(()=>[...t[2]||(t[2]=[e("shipsw",-1)])]),_:1}),t[5]||(t[5]=e(" 校对：",-1)),a(n,{href:"https://github.com/wxy"},{default:o(()=>[...t[3]||(t[3]=[e("wxy",-1)])]),_:1})]),p("p",null,[t[8]||(t[8]=e("本文由 ",-1)),a(n,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[6]||(t[6]=[e("LCTT",-1)])]),_:1}),t[9]||(t[9]=e(" 原创翻译，",-1)),a(n,{href:"http://linux.cn/"},{default:o(()=>[...t[7]||(t[7]=[e("Linux中国",-1)])]),_:1}),t[10]||(t[10]=e(" 荣誉推出",-1))])])}const C=r(D,[["render",m]]);export{x as __pageData,C as default};
